let items = $input.all();

if (items.length === 1 && items[0].json && Object.keys(items[0].json).length === 0) {
    items = [];
}

let totalEvents = 0;
let totalInfos = 0;
let totalErrors = 0;
let totalWarns = 0;

const uniqueDates = new Set();
const uniqueServers = new Set();
const patterns = {};

items.forEach(item => {
    const row = item.json;
    const msg = row.cleanmessage || '';
    let level = row.loglevel || 'INFO';
    const count = parseInt(row.count || 1);
    const serverName = row.server_name || 'UNKNOWN';
    const dateStr = row.log_date ? row.log_date.split('T')[0] : 'N/A';
    const times = row.times || 'Нет данных';
    const aiResponse = row.answer || '_Анализ еще не выполнялся или лог ожидает обработки._';

    if (level === 'ERROR' || level === 'FATAL') {
        totalErrors += count;
    }
    else if (level === 'WARN' || level === 'WARNING') {
        totalWarns += count;
    }
    else {
        totalInfos += count;
    }

    totalEvents += count;

    uniqueDates.add(dateStr);
    uniqueServers.add(serverName);

    if (!patterns[msg]) {
        patterns[msg] = {
            message: msg,
            level: level,
            totalCount: 0,
            aiResponse: aiResponse,
            servers: {},
            allDates: new Set(),
            allServers: new Set()
        };
    }

    const p = patterns[msg];
    p.totalCount += count;
    p.allDates.add(dateStr);
    p.allServers.add(serverName);

    if (!p.servers[serverName]) {
        p.servers[serverName] = {
            serverName: serverName,
            totalCount: 0,
            dates: {}
        };
    }

    const s = p.servers[serverName];
    s.totalCount += count;

    if (!s.dates[dateStr]) {
        s.dates[dateStr] = {
            times: [],
            count: 0
        };
    }
    const d = s.dates[dateStr];
    d.count += count;
    if (times && times !== 'Нет данных') {
        d.times.push(times);
    }
});

let rowsHtml = '';

Object.values(patterns).forEach(p => {
    const level = p.level;
    const badgeClass =
        (level === 'ERROR' || level === 'FATAL') ? 'badge-error'
        : (level === 'WARN' || level === 'WARNING') ? 'badge-warn'
        : 'badge-info';

    const safeMsg = p.message.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const encodedMarkdown = encodeURIComponent(p.aiResponse);
    const datesAttr = Array.from(p.allDates).join(' ');
    const serversAttr = Array.from(p.allServers).map(s => s.replace(/\s+/g, '_')).join(' ');

    let serversHtml = '';
    Object.values(p.servers).forEach(s => {
        const safeServerName = s.serverName.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

        let tableRowsHtml = '';
        Object.keys(s.dates).forEach(dStr => {
            const dateData = s.dates[dStr];
            const chron = dateData.times.length > 0 ? dateData.times.join(', ') : 'Нет данных';
            tableRowsHtml += `
                <tr data-row-date="${dStr}">
                    <td>${dStr}</td>
                    <td><code>${chron}</code></td>
                    <td>${dateData.count}</td>
                </tr>`;
        });

        serversHtml += `
        <details class="server-details" data-server-name="${s.serverName.replace(/"/g, '&quot;')}">
            <summary class="server-summary">
                <span>🖥️ ${safeServerName}</span>
                <span class="server-count">Повторов: <strong>${s.totalCount}</strong></span>
            </summary>
            <div class="server-content">
                <table class="server-table">
                    <thead>
                        <tr>
                            <th>Дата</th>
                            <th>Хронология</th>
                            <th>Повторов за текущий день</th>
                        </tr>
                    </thead>
                    <tbody>${tableRowsHtml}
                    </tbody>
                </table>
            </div>
        </details>`;
    });

    rowsHtml += `
    <div class="log-card" data-level="${level}" data-dates="${datesAttr}" data-servers="${serversAttr}">
        <div class="log-header">
            <span class="badge ${badgeClass}">${level}</span>
            <span class="log-count">🔁 Повторов: <strong>${p.totalCount}</strong></span>
        </div>
        <div class="log-body">
            <code>${safeMsg}</code>
        </div>
        <div class="log-servers-section">${serversHtml}
        </div>
        <details class="ai-details">
            <summary class="ai-summary">
                💡 Анализ инцидента и решение от ИИ (Qwen-Coder)
            </summary>
            <div class="ai-content" data-markdown="${encodedMarkdown}">
                Загрузка анализа...
            </div>
        </details>
    </div>`;
});

const dateOptions = Array.from(uniqueDates).sort().reverse().map(d => `<option value="${d}">${d}</option>`).join('');
const serverOptions = Array.from(uniqueServers).sort().map(s => `<option value="${s}">${s}</option>`).join('');

const html = `<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<title>AI Log Observer (Нормализованный)</title>
<script src="https://cdn.jsdelivr.net/npm/marked/marked.min.js"></script>
<style>
body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background-color: #0f172a; color: #e2e8f0; margin: 0; padding: 20px; }
.container { max-width: 1200px; margin: 0 auto; }
.header { background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); padding: 25px; border-radius: 12px; border: 1px solid #334155; margin-bottom: 25px; position: relative; }
.header h1 { margin: 0; font-size: 24px; color: #38bdf8; }
.header p { margin: 5px 0 0 0; color: #94a3b8; font-size: 14px; }
.auth-badge { position: absolute; top: 25px; right: 25px; background-color: #064e3b; color: #34d399; padding: 6px 12px; border-radius: 20px; font-size: 12px; font-weight: bold; border: 1px solid #059669; }
.stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-bottom: 25px; }
.stat-card { background-color: #1e293b; padding: 20px; border-radius: 10px; border: 1px solid #334155; text-align: center; }
.stat-card h3 { margin: 0; font-size: 14px; color: #94a3b8; text-transform: uppercase; }
.stat-card .value { font-size: 32px; font-weight: bold; margin-top: 10px; }
.stat-blue { color: #38bdf8; }
.stat-amber { color: #fbbf24; }
.stat-red { color: #f87171; }
.filters { margin-bottom: 20px; display: flex; flex-wrap: wrap; gap: 15px; align-items: center; }
.filter-group { display: flex; gap: 10px; }
.dropdown-group { display: flex; gap: 10px; margin-left: auto; align-items: center; }
.filter-btn { background-color: #1e293b; border: 1px solid #334155; color: #e2e8f0; padding: 8px 16px; border-radius: 6px; cursor: pointer; font-weight: 500; }
.filter-btn:hover { background-color: #334155; }
.filter-btn.active { background-color: #38bdf8; color: #0f172a; border-color: #38bdf8; }
select { background-color: #1e293b; color: #e2e8f0; border: 1px solid #334155; padding: 8px 12px; border-radius: 6px; outline: none; font-size: 14px; }
.log-card { background-color: #1e293b; border: 1px solid #334155; border-radius: 8px; padding: 15px; margin-bottom: 15px; }
.log-header { display: flex; flex-wrap: wrap; gap: 15px; align-items: center; margin-bottom: 10px; font-size: 13px; }
.badge { padding: 4px 8px; border-radius: 4px; font-weight: bold; font-size: 11px; }
.badge-error { background-color: #7f1d1d; color: #fca5a5; }
.badge-warn { background-color: #78350f; color: #fcd34d; }
.badge-info { background-color: #0c4a6e; color: #7dd3fc; }
.log-count { color: #cbd5e1; }
.log-body { background-color: #0f172a; padding: 12px; border-radius: 6px; border: 1px solid #1e293b; overflow-x: auto; margin-bottom: 12px; }
.log-body code { font-family: Consolas, Monaco, monospace; color: #f1f5f9; font-size: 13px; white-space: pre-wrap; }
.log-servers-section { margin-bottom: 12px; }
.server-details { background-color: #141b2d; border: 1px solid #27272a; border-radius: 6px; margin-bottom: 6px; overflow: hidden; }
.server-summary { padding: 10px 15px; cursor: pointer; background-color: #0b0f19; font-size: 13px; color: #cbd5e1; display: flex; justify-content: space-between; align-items: center; }
.server-summary:hover { background-color: #1e293b; }
.server-count { color: #cbd5e1; font-size: 12px; }
.server-content { padding: 15px; background-color: #090d16; border-top: 1px solid #27272a; }
.server-table { border-collapse: collapse; width: 100%; font-size: 12px; color: #cbd5e1; }
.server-table th, .server-table td { border: 1px solid #334155; padding: 8px; text-align: left; }
.server-table th { background-color: #1e293b; color: #38bdf8; }
.server-table td code { font-family: Consolas, Monaco, monospace; color: #fbbf24; }
.ai-details { background-color: #090d16; border: 1px solid #27272a; border-radius: 6px; overflow: hidden; }
.ai-summary { padding: 10px 15px; cursor: pointer; background-color: #141b2d; font-size: 13px; font-weight: bold; color: #a78bfa; }
.ai-summary:hover { background-color: #1d2844; }
.ai-content { padding: 15px; font-size: 13px; line-height: 1.6; color: #cbd5e1; border-top: 1px solid #27272a; background-color: #0b0f19; }
.ai-content h1, .ai-content h2, .ai-content h3, .ai-content h4 { color: #7dd3fc; }
.ai-content code { background-color: #1e293b; padding: 2px 5px; border-radius: 4px; color: #fbbf24; }
.ai-content pre { background-color: #0f172a; padding: 12px; border-radius: 6px; overflow-x: auto; }
.ai-content table { border-collapse: collapse; width: 100%; margin-top: 10px; }
.refresh-btn { position: absolute; top: 65px; right: 25px; background-color: #38bdf8; color: #0f172a; border: none; border-radius: 6px; padding: 8px 14px; cursor: pointer; font-weight: 600; }
.refresh-btn:hover { background-color: #7dd3fc; }
.refresh-btn:disabled { opacity: 0.7; cursor: wait; }
.ai-content th, .ai-content td { border: 1px solid #334155; padding: 8px; }
.ai-content th { background-color: #1e293b; }
.no-data { text-align: center; color: #64748b; padding: 40px; font-size: 16px; }
</style>
</head>
<body>
<div class="container">
    <div class="header">
        <h1>AI Log Observer</h1>
        <p>Детализированный учет по Датам и Серверам</p>
        <div class="auth-badge">🟢 Режим: Без ограничений</div>
        <button class="refresh-btn" onclick="refreshDashboard()">🔄 Обновить</button>
    </div>
    <div class="stats-grid">
        <div class="stat-card"><h3>Уникальных записей</h3><div class="value stat-blue">${Object.keys(patterns).length}</div></div>
        <div class="stat-card"><h3>Всего событий (сумма)</h3><div class="value stat-blue">${totalEvents}</div></div>
        <div class="stat-card"><h3>Предупреждения (WARN)</h3><div class="value stat-amber">${totalWarns}</div></div>
        <div class="stat-card"><h3>Критические ошибки (ERROR)</h3><div class="value stat-red">${totalErrors}</div></div>
    </div>
    <div class="filters">
        <div class="filter-group">
            <button class="filter-btn active" data-btn-level="ALL">Все уровни</button>
            <button class="filter-btn" data-btn-level="ERROR">ERROR</button>
            <button class="filter-btn" data-btn-level="WARN">WARN</button>
            <button class="filter-btn" data-btn-level="INFO">INFO</button>
        </div>
        <div class="dropdown-group">
            <label style="color:#94a3b8; font-size:14px;">📅 Дата:</label>
            <select id="filter-date">
                <option value="ALL">Все даты</option>
                ${dateOptions}
            </select>
            <label style="color:#94a3b8; font-size:14px; margin-left:10px;">🖥️ Сервер:</label>
            <select id="filter-server">
                <option value="ALL">Все серверы</option>
                ${serverOptions}
            </select>
        </div>
    </div>
    <div class="log-feed">
        ${rowsHtml || '<div class="no-data">За последние 10 дней инцидентов не обнаружено. База пуста.</div>'}
    </div>
</div>
<script>
let activeLevel = 'ALL';
function applyFilters() {
    const activeDate = document.getElementById('filter-date').value;
    const activeServer = document.getElementById('filter-server').value;
    document.querySelectorAll('.log-card').forEach(card => {
        const cLevel = card.getAttribute('data-level');
        const cDatesAttr = card.getAttribute('data-dates') || '';
        const cServersAttr = card.getAttribute('data-servers') || '';
        const cDates = cDatesAttr.split(' ');
        const cServers = cServersAttr.split(' ').map(s => s.replace(/_/g, ' '));
        const matchL = activeLevel === 'ALL' || cLevel === activeLevel || (activeLevel === 'ERROR' && cLevel === 'FATAL') || (activeLevel === 'WARN' && cLevel === 'WARNING');
        const matchD = activeDate === 'ALL' || cDates.includes(activeDate);
        const matchS = activeServer === 'ALL' || cServers.includes(activeServer);
        if (!matchL) { card.style.display = 'none'; return; }
        let cardHasVisibleServers = false;
        card.querySelectorAll('.server-details').forEach(serverBlock => {
            const serverName = serverBlock.getAttribute('data-server-name');
            const matchS = activeServer === 'ALL' || serverName === activeServer;
            if (!matchS) { serverBlock.style.display = 'none'; return; }
            let serverHasVisibleDates = false;
            serverBlock.querySelectorAll('.server-table tbody tr').forEach(row => {
                const rowDate = row.getAttribute('data-row-date');
                const matchD = activeDate === 'ALL' || rowDate === activeDate;
                if (matchD) { row.style.display = ''; serverHasVisibleDates = true; } else { row.style.display = 'none'; }
            });
            if (serverHasVisibleDates) { serverBlock.style.display = 'block'; cardHasVisibleServers = true; } else { serverBlock.style.display = 'none'; }
        });
        card.style.display = cardHasVisibleServers ? 'block' : 'none';
    });
}
document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
        document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        activeLevel = e.target.getAttribute('data-btn-level');
        applyFilters();
    });
});
document.getElementById('filter-date').addEventListener('change', applyFilters);
document.getElementById('filter-server').addEventListener('change', applyFilters);
document.querySelectorAll('.ai-content').forEach(el => {
    const encoded = el.dataset.markdown || '';
    const markdown = decodeURIComponent(encoded);
    if (markdown.trim()) { el.innerHTML = marked.parse(markdown); } else { el.innerHTML = '<em>Анализ отсутствует</em>'; }
});
function refreshDashboard() {
    const btn = document.querySelector('.refresh-btn');
    btn.disabled = true;
    btn.innerHTML = '⏳ Обновление...';
    location.reload();
}
setTimeout(() => { location.reload(); }, 300000);
</script>
</body>
</html>`;

return [
    {
        json: {
            html
        }
    }
];
